import csv, io, os, re
from datetime import datetime


def _date(s):
    s = (s or '').strip()
    for f in ('%Y-%m-%d', '%d.%m.%Y', '%d. %m. %Y', '%d/%m/%Y'):
        try:
            return datetime.strptime(s, f).date().isoformat()
        except ValueError:
            pass
    return None


def _read(path):
    raw = open(path, 'rb').read()
    try:
        t = raw.decode('utf-8-sig')
    except UnicodeDecodeError:
        t = raw.decode('cp1250', errors='replace')
    first = t.split('\n', 1)[0]
    delim = ';' if first.count(';') > first.count(',') else ','
    rows = list(csv.DictReader(io.StringIO(t), delimiter=delim))
    return [{(k or '').strip().lower(): (v or '').strip() for k, v in r.items()} for r in rows]


def _opt_date(inp, key):
    v = inp.get(key)
    if v is None or v == '':
        return None
    if not isinstance(v, str) or _date(v) is None:
        raise ValueError('invalid date in ' + key + ': ' + str(v))
    return _date(v)


def run(inp):
    if not isinstance(inp, dict) or not isinstance(inp.get('folder'), str) or not inp['folder']:
        raise ValueError('input must contain a non-empty string field folder')
    for k in ('customer_filter', 'channel_filter'):
        if inp.get(k) is not None and not isinstance(inp.get(k), str):
            raise ValueError(k + ' must be a string')
    fd = _opt_date(inp, 'from_date')
    td = _opt_date(inp, 'to_date')
    if fd and td and fd > td:
        raise ValueError('from_date is after to_date')
    base = os.path.join('.', 'inbox', inp['folder'])
    if not os.path.isdir(base):
        raise ValueError('folder not found: ' + inp['folder'])
    p = os.path.join(base, 'customer_feedback.csv')
    out = {'records': [], 'errors': []}
    if not os.path.exists(p):
        out['errors'].append('customer_feedback.csv missing')
        return out
    cf = (inp.get('customer_filter') or '').strip().lower()
    chf = (inp.get('channel_filter') or '').strip().lower()
    n = 0
    for i, r in enumerate(_read(p), 2):
        d = _date(r.get('date'))
        if d is None or not r.get('text'):
            out['errors'].append('customer_feedback.csv line %d unparsable' % i)
            continue
        n += 1
        rec = {'id': n, 'date': d, 'customer': r.get('customer', ''),
               'channel': r.get('channel', ''), 'text': r['text']}
        if fd and d < fd:
            continue
        if td and d > td:
            continue
        if cf and cf not in rec['customer'].lower():
            continue
        if chf and chf != rec['channel'].lower():
            continue
        out['records'].append(rec)
    return out

